// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title IPriceFeed
 * @dev Interface for a price oracle.
 */
interface IPriceFeed {
    /**
     * @dev Returns the latest price of an asset.
     * @return The price, scaled by 1e18 (WAD).
     */
    function getLatestPrice() external view returns (uint256);
}

/**
 * @title MiniLendingPool
 * @author Your Name Here
 * @notice A simplified, overcollateralized lending pool for a single ERC20 asset.
 * @dev This contract allows users to lend and borrow a `depositToken` against a `collateralToken`.
 * Interest rates are variable based on pool utilization. It includes liquidation logic
 * and is secured with OpenZeppelin's ReentrancyGuard, Pausable, and Ownable contracts.
 * This contract is for demonstration purposes and lacks features of a production system.
 */
contract MiniLendingPool is Ownable, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // --- Constants ---

    uint256 internal constant WAD = 1e18; // For token amounts and prices
    uint256 internal constant RAY = 1e27; // For interest rates and indexes
    uint256 internal constant BASIS_POINTS = 10000; // For percentages (e.g., 75% is 7500)
    uint256 internal constant SECONDS_PER_YEAR = 31536000;

    // --- State Variables ---

    // Assets
    IERC20 public immutable depositToken;
    IERC20 public immutable collateralToken;

    // Oracle
    IPriceFeed public priceFeed;
    bool public oracleBroken;

    // User Data
    mapping(address => uint256) public collateralBalance; // User -> collateral amount
    mapping(address => uint256) public borrowPrincipal;   // User -> borrow principal (at index=1)
    mapping(address => uint256) public depositShares;     // User -> liquidity shares

    // Pool State
    uint256 public totalCollateral;
    uint256 public totalBorrowPrincipal;
    uint256 public totalDepositShares;

    // Interest Rate Indexes
    uint256 public depositIndex; // RAY
    uint256 public borrowIndex;  // RAY
    uint256 public lastIndexUpdateTimestamp;

    // Lending Parameters
    uint256 public loanToValue;          // e.g., 7500 for 75%
    uint256 public liquidationThreshold; // e.g., 8000 for 80%
    uint256 public liquidationBonus;     // e.g., 10500 for 105% (5% bonus)
    uint256 public closeFactor;          // e.g., 5000 for 50%
    uint256 public baseRate;             // Annual base rate in RAY (e.g., 2% is 2 * 1e25)
    uint256 public slopeRate;            // Annual slope rate in RAY (e.g., 20% is 20 * 1e25)

    // --- Events ---

    event LiquidityAdded(address indexed user, uint256 amount, uint256 shares);
    event LiquidityRemoved(address indexed user, uint256 amount, uint256 shares);
    event CollateralSupplied(address indexed user, uint256 amount);
    event CollateralWithdrawn(address indexed user, uint256 amount);
    event Borrowed(address indexed user, uint256 amount);
    event Repaid(address indexed user, uint256 repayAmount, uint256 newDebt);
    event Liquidated(
        address indexed liquidator,
        address indexed borrower,
        uint256 repayAmount,
        uint256 seizedCollateralAmount
    );
    event LendingTermsSet(
        uint256 newLoanToValue,
        uint256 newLiquidationThreshold,
        uint256 newLiquidationBonus,
        uint256 newCloseFactor,
        uint256 newBaseRate,
        uint256 newSlopeRate
    );
    event PriceFeedUpdated(address newPriceFeed);
    event OracleCircuitBreakerToggled(bool isBroken);

    // --- Constructor ---

    constructor(
        address _depositToken,
        address _collateralToken,
        address _priceFeed
    ) {
        require(_depositToken != address(0) && _collateralToken != address(0) && _priceFeed != address(0), "Zero address");
        require(_depositToken != _collateralToken, "Tokens must be different");

        depositToken = IERC20(_depositToken);
        collateralToken = IERC20(_collateralToken);
        priceFeed = IPriceFeed(_priceFeed);

        depositIndex = RAY;
        borrowIndex = RAY;
        lastIndexUpdateTimestamp = block.timestamp;

        _setLendingTerms(7500, 8000, 10500, 5000, 2 * 1e25, 20 * 1e25); // 2% base, 20% slope
    }

    // --- Core Logic ---

    /**
     * @dev Updates the deposit and borrow indexes based on accrued interest.
     * This internal function is called before any operation that depends on up-to-date balances.
     */
    function _updateIndexes() internal {
        if (block.timestamp <= lastIndexUpdateTimestamp) {
            return;
        }
        uint256 timeDelta = block.timestamp - lastIndexUpdateTimestamp;

        uint256 totalDeposits = getTotalDeposits();
        if (totalDeposits == 0 || totalBorrowPrincipal == 0) {
            lastIndexUpdateTimestamp = block.timestamp;
            return;
        }

        uint256 currentBorrows = (totalBorrowPrincipal * borrowIndex) / RAY;
        uint256 utilization = (currentBorrows * WAD) / totalDeposits;

        uint256 annualBorrowRate = baseRate + ((slopeRate * utilization) / WAD);
        uint256 borrowInterest = (borrowIndex * annualBorrowRate * timeDelta) / (SECONDS_PER_YEAR * RAY);
        if (borrowInterest > 0) {
            borrowIndex += borrowInterest;
        }

        uint256 annualDepositRate = (annualBorrowRate * utilization) / WAD;
        uint256 depositInterest = (depositIndex * annualDepositRate * timeDelta) / (SECONDS_PER_YEAR * RAY);
        if (depositInterest > 0) {
            depositIndex += depositInterest;
        }

        lastIndexUpdateTimestamp = block.timestamp;
    }

    // --- Lender Functions ---

    /**
     * @notice Deposits depositToken into the pool to earn interest.
     * @param amount The amount of depositToken to supply.
     */
    function deposit(uint256 amount) external whenNotPaused nonReentrant {
        require(amount > 0, "Amount must be > 0");
        _updateIndexes();

        uint256 shares = (amount * RAY) / depositIndex;
        require(shares > 0, "Amount too small");

        depositShares[msg.sender] += shares;
        totalDepositShares += shares;

        emit LiquidityAdded(msg.sender, amount, shares);
        depositToken.safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Withdraws depositToken from the pool by redeeming shares.
     * @dev Can be called even when paused to allow users to exit.
     * @param shares The number of shares to redeem.
     */
    function withdraw(uint256 shares) external nonReentrant {
        require(shares > 0, "Shares must be > 0");
        require(depositShares[msg.sender] >= shares, "Insufficient shares");
        _updateIndexes();

        uint256 amount = (shares * depositIndex) / RAY;
        require(getCash() >= amount, "Insufficient liquidity");

        depositShares[msg.sender] -= shares;
        totalDepositShares -= shares;

        emit LiquidityRemoved(msg.sender, amount, shares);
        depositToken.safeTransfer(msg.sender, amount);
    }

    // --- Borrower Functions ---

    /**
     * @notice Supplies collateral to the pool.
     * @param amount The amount of collateralToken to supply.
     */
    function supplyCollateral(uint256 amount) external whenNotPaused nonReentrant {
        require(amount > 0, "Amount must be > 0");
        collateralBalance[msg.sender] += amount;
        totalCollateral += amount;
        emit CollateralSupplied(msg.sender, amount);
        collateralToken.safeTransferFrom(msg.sender, address(this), amount);
    }

    /**
     * @notice Withdraws collateral from the pool.
     * @dev The withdrawal is only allowed if the user's health factor remains above 1.
     * @param amount The amount of collateralToken to withdraw.
     */
    function withdrawCollateral(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(collateralBalance[msg.sender] >= amount, "Insufficient collateral");

        _updateIndexes(); // Update indexes to get latest debt value

        // Optimistically update balance to check health factor
        collateralBalance[msg.sender] -= amount;
        require(getHealthFactor(msg.sender) >= WAD, "Health factor too low");

        // Finalize state changes
        totalCollateral -= amount;

        emit CollateralWithdrawn(msg.sender, amount);
        collateralToken.safeTransfer(msg.sender, amount);
    }

    /**
     * @notice Borrows depositToken against supplied collateral.
     * @param amount The amount of depositToken to borrow.
     */
    function borrow(uint256 amount) external whenNotPaused nonReentrant {
        require(amount > 0, "Amount must be > 0");
        require(!oracleBroken, "Oracle is broken");
        require(getCash() >= amount, "Insufficient liquidity");

        _updateIndexes();

        // Check if the new borrow is allowed by LTV
        uint256 collateralValue = getCollateralValue(msg.sender);
        uint256 borrowLimit = (collateralValue * loanToValue) / BASIS_POINTS;
        uint256 newDebt = getBorrowBalance(msg.sender) + amount;
        require(newDebt <= borrowLimit, "Borrow exceeds LTV");

        uint256 principalToBorrow = (amount * RAY) / borrowIndex;
        borrowPrincipal[msg.sender] += principalToBorrow;
        totalBorrowPrincipal += principalToBorrow;

        emit Borrowed(msg.sender, amount);
        depositToken.safeTransfer(msg.sender, amount);
    }

    /**
     * @notice Repays a borrow. Can be a partial or full repayment.
     * @param amount The amount of depositToken to repay. Use type(uint256).max for full repayment.
     */
    function repay(uint256 amount) external nonReentrant {
        require(amount > 0, "Amount must be > 0");
        _updateIndexes();

        uint256 currentDebt = getBorrowBalance(msg.sender);
        require(currentDebt > 0, "No debt to repay");

        uint256 repayAmount = amount >= currentDebt ? currentDebt : amount;

        uint256 principalToRepay = (repayAmount * RAY) / borrowIndex;
        borrowPrincipal[msg.sender] -= principalToRepay;
        totalBorrowPrincipal -= principalToRepay;

        emit Repaid(msg.sender, repayAmount, currentDebt - repayAmount);
        depositToken.safeTransferFrom(msg.sender, address(this), repayAmount);
    }

    // --- Liquidation ---

    /**
     * @notice Liquidates an undercollateralized position.
     * @dev Anyone can liquidate a position if its health factor is below 1.
     * The liquidator repays a portion of the debt and seizes collateral at a discount.
     * @param borrower The address of the borrower to liquidate.
     */
    function liquidate(address borrower) external whenNotPaused nonReentrant {
        _updateIndexes();

        require(getHealthFactor(borrower) < WAD, "Position is not liquidatable");

        uint256 borrowerDebt = getBorrowBalance(borrower);
        uint256 repayAmount = (borrowerDebt * closeFactor) / BASIS_POINTS;
        require(repayAmount > 0, "Debt is zero");

        uint256 collateralPrice = priceFeed.getLatestPrice();
        require(collateralPrice > 0, "Invalid collateral price");

        uint256 seizedCollateralValue = (repayAmount * liquidationBonus) / BASIS_POINTS;
        uint256 seizedCollateralAmount = (seizedCollateralValue * WAD) / collateralPrice;

        require(collateralBalance[borrower] >= seizedCollateralAmount, "Not enough collateral to seize");

        uint256 principalToRepay = (repayAmount * RAY) / borrowIndex;
        borrowPrincipal[borrower] -= principalToRepay;
        totalBorrowPrincipal -= principalToRepay;
        collateralBalance[borrower] -= seizedCollateralAmount;
        totalCollateral -= seizedCollateralAmount;

        emit Liquidated(msg.sender, borrower, repayAmount, seizedCollateralAmount);

        depositToken.safeTransferFrom(msg.sender, address(this), repayAmount);
        collateralToken.safeTransfer(msg.sender, seizedCollateralAmount);
    }

    // --- Admin Functions ---

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    function setLendingTerms(
        uint256 newLoanToValue,
        uint256 newLiquidationThreshold,
        uint256 newLiquidationBonus,
        uint256 newCloseFactor,
        uint256 newBaseRate,
        uint256 newSlopeRate
    ) external onlyOwner {
       _setLendingTerms(
           newLoanToValue, newLiquidationThreshold, newLiquidationBonus,
           newCloseFactor, newBaseRate, newSlopeRate
       );
    }

    function _setLendingTerms(
        uint256 _ltv, uint256 _liqThreshold, uint256 _liqBonus,
        uint256 _cFactor, uint256 _bRate, uint256 _sRate
    ) internal {
        require(_ltv < _liqThreshold && _liqThreshold <= BASIS_POINTS, "Invalid LTV/Threshold");
        require(_liqBonus >= BASIS_POINTS, "Bonus must be >= 100%");
        require(_cFactor > 0 && _cFactor <= BASIS_POINTS, "Invalid close factor");

        loanToValue = _ltv;
        liquidationThreshold = _liqThreshold;
        liquidationBonus = _liqBonus;
        closeFactor = _cFactor;
        baseRate = _bRate;
        slopeRate = _sRate;

        emit LendingTermsSet(_ltv, _liqThreshold, _liqBonus, _cFactor, _bRate, _sRate);
    }

    function setPriceFeed(address newPriceFeed) external onlyOwner {
        require(newPriceFeed != address(0), "Zero address");
        priceFeed = IPriceFeed(newPriceFeed);
        emit PriceFeedUpdated(newPriceFeed);
    }

    function toggleOracleCircuitBreaker(bool isBroken) external onlyOwner {
        oracleBroken = isBroken;
        emit OracleCircuitBreakerToggled(isBroken);
    }

    // --- View Functions ---

    function getCash() public view returns (uint256) { return depositToken.balanceOf(address(this)); }
    function getTotalDeposits() public view returns (uint256) { return (totalDepositShares * depositIndex) / RAY; }
    function getTotalBorrows() public view returns (uint256) { return (totalBorrowPrincipal * borrowIndex) / RAY; }

    function getUtilizationRate() public view returns (uint256) {
        uint256 totalDeposits = getTotalDeposits();
        if (totalDeposits == 0) return 0;
        return (getTotalBorrows() * WAD) / totalDeposits;
    }

    function getCurrentBorrowRate() public view returns (uint256) {
        return baseRate + ((slopeRate * getUtilizationRate()) / WAD);
    }

    function getBorrowBalance(address user) public view returns (uint256) { return (borrowPrincipal[user] * borrowIndex) / RAY; }
    function getDepositBalance(address user) public view returns (uint256) { return (depositShares[user] * depositIndex) / RAY; }

    function getCollateralValue(address user) public view returns (uint256) {
        uint256 userCollateral = collateralBalance[user];
        if (userCollateral == 0) return 0;
        uint256 collateralPrice = priceFeed.getLatestPrice();
        return (userCollateral * collateralPrice) / WAD;
    }

    function getHealthFactor(address user) public view returns (uint256) {
        uint256 borrowValue = getBorrowBalance(user);
        if (borrowValue == 0) return type(uint256).max;

        uint256 collateralValue = getCollateralValue(user);
        uint256 thresholdCollateralValue = (collateralValue * liquidationThreshold) / BASIS_POINTS;

        return (thresholdCollateralValue * WAD) / borrowValue;
    }

    function getAccountInfo(address user) external view returns (
        uint256 collateral, uint256 deposit, uint256 debt, uint256 healthFactor
    ) {
        collateral = collateralBalance[user];
        deposit = getDepositBalance(user);
        debt = getBorrowBalance(user);
        healthFactor = getHealthFactor(user);
    }
}


/**
 * @title DemoPriceFeed
 * @dev A simple, manually updatable price feed for demonstration purposes.
 * In a real-world scenario, this would be a robust oracle like Chainlink.
 */
contract DemoPriceFeed is IPriceFeed, Ownable {
    uint256 private latestPrice;

    event PriceUpdated(uint256 newPrice);

    constructor(uint256 initialPrice) {
        updatePrice(initialPrice);
    }

    function getLatestPrice() external view override returns (uint256) {
        return latestPrice;
    }

    function updatePrice(uint256 newPrice) public onlyOwner {
        require(newPrice > 0, "Price must be positive");
        latestPrice = newPrice;
        emit PriceUpdated(newPrice);
    }
}

